'use client'

import * as React from 'react'
import { ToggleGroup } from 'radix-ui'
import { cva } from 'class-variance-authority'
import { cn } from '@/lib/utils'
import { useSlidingIndicator } from '@/registry/satin/ui/sliding-indicator'

/**
 * SegmentedControl, from the uiKit `segmented control` page: 2–5 segments that switch
 * views or filters in place. One segment is always selected; the selected pill slides under
 * the labels to the new segment, as in Tabs and Pagination (sliding-indicator.tsx: 300 ms,
 * the leading edge first): a white card with Shadow/sm in Light. Arrow keys move between segments.
 * Values 1:1 with the uiKit `_segmentedControl/item` (3080:20278) and `SegmentedControl` (3080:21247) sets.
 *
 * Other props, `ref` included, go to the track (the Radix ToggleGroup root, a `group`).
 */
type Size = 'xs' | 'md' | 'lg'
type Shape = 'default' | 'rounded'

export interface SegmentedControlItem {
  value: string
  label: React.ReactNode
  icon?: React.ReactNode
  disabled?: boolean
}

export interface SegmentedControlProps extends Omit<React.ComponentProps<'div'>, 'defaultValue' | 'dir' | 'children'> {
  items: SegmentedControlItem[]
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  size?: Size
  shape?: Shape
  /** A 1px border-subtle outline around the track. */
  border?: boolean
  fullWidth?: boolean
  /** Required when the segments have no visible text of their own. */
  'aria-label'?: string
  className?: string
}

const track = cva('sa:relative sa:isolate sa:inline-flex sa:items-center sa:gap-0.5 sa:bg-bg-muted sa:p-1', {
  variants: {
    shape: { default: 'sa:rounded-lg', rounded: 'sa:rounded-pill' },
    border: { true: 'sa:border sa:border-border-subtle', false: '' },
    fullWidth: { true: 'sa:flex sa:w-full', false: '' },
  },
})

const segment = cva(
  [
    'sa:relative sa:z-10 sa:inline-flex sa:items-center sa:justify-center sa:font-medium sa:whitespace-nowrap sa:text-text-muted sa:select-none',
    'sa:transition-[color,background-color,box-shadow] sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
    'sa:satin-hover:text-text-default sa:data-[state=on]:text-text-default',
    'sa:satin-pressed:bg-component-segmented-pressed sa:satin-pressed:text-text-default',
    'sa:focus-visible:outline-none sa:satin-focus:text-text-default sa:satin-focus:[box-shadow:0_0_0_2px_var(--action-focus-ring)]',
    'sa:disabled:pointer-events-none sa:disabled:text-text-subtle',
    'sa:[&_svg]:pointer-events-none sa:[&_svg]:shrink-0 sa:[&_svg]:[stroke-width:1.875]',
  ],
  {
    variants: {
      size: {
        xs: 'sa:h-control-height-xs sa:gap-1 sa:px-2.5 sa:text-sm sa:[&_svg]:size-icon-size-sm',
        md: 'sa:h-control-height sa:gap-1.5 sa:px-3 sa:text-sm sa:[&_svg]:size-icon-size',
        lg: 'sa:h-control-height-lg sa:gap-1.5 sa:px-4 sa:text-base sa:[&_svg]:size-icon-size',
      },
      shape: { default: 'sa:rounded-sm', rounded: 'sa:rounded-pill' },
      fullWidth: { true: 'sa:flex-1', false: '' },
    },
  },
)

export function SegmentedControl({
  items,
  value: valueProp,
  defaultValue,
  onValueChange,
  size = 'md',
  shape = 'default',
  border = false,
  fullWidth = false,
  className,
  ref,
  ...props
}: SegmentedControlProps) {
  const [inner, setInner] = React.useState(defaultValue ?? items[0]?.value ?? '')
  const value = valueProp ?? inner
  const trackRef = React.useRef<HTMLDivElement>(null)
  // The app's ref and ours, on the track.
  const setTrack = React.useCallback(
    (node: HTMLDivElement | null) => {
      trackRef.current = node
      if (typeof ref === 'function') ref(node)
      else if (ref) ref.current = node
    },
    [ref],
  )
  // The pill slides under the selected segment (sliding-indicator.tsx).
  const pill = useSlidingIndicator(trackRef, '[data-state="on"]', `${value}|${size}|${fullWidth}|${items.length}`)

  return (
    <ToggleGroup.Root
      {...props}
      ref={setTrack}
      type="single"
      value={value}
      onValueChange={(next) => {
        // A segmented control never ends up with nothing selected.
        if (!next) return
        setInner(next)
        onValueChange?.(next)
      }}
      data-slot="segmented-control"
      className={cn(track({ shape, border, fullWidth }), className)}
    >
      <span
        ref={pill.ref}
        aria-hidden
        className={cn(
          'sa:pointer-events-none sa:absolute sa:top-1 sa:bottom-1 sa:left-0 sa:z-0 sa:bg-component-segmented-selected sa:opacity-0 sa:[box-shadow:0_1px_3px_0_var(--effect-shadow-sm),0_1px_2px_-1px_var(--effect-shadow-sm)]',
          shape === 'sa:rounded' ? 'sa:rounded-pill' : 'sa:rounded-sm',
        )}
      />
      {items.map((item) => (
        <ToggleGroup.Item
          key={item.value}
          value={item.value}
          disabled={item.disabled}
          className={cn(
            segment({ size, shape, fullWidth }),
            // Unselected focus: bg/muted under the ring. Selected focus keeps the pill's fill.
            'sa:data-[state=off]:satin-focus:bg-bg-muted',
            // Before the pill is measured (server render), the selected segment paints its own fill.
            !pill.ready && 'sa:data-[state=on]:bg-component-segmented-selected sa:data-[state=on]:[box-shadow:0_1px_3px_0_var(--effect-shadow-sm),0_1px_2px_-1px_var(--effect-shadow-sm)]',
          )}
        >
          {item.icon}
          {item.label}
        </ToggleGroup.Item>
      ))}
    </ToggleGroup.Root>
  )
}
